namespace PrestaShop\Module\FexaAiConnector\Mcp\Tools;

use PhpMcp\Server\Attributes\McpTool;
use PhpMcp\Server\Attributes\Schema;
use Db;

/**
 * Store + serve the shop's /llms.txt — a machine-readable AEO map of the store
 * for AI answer engines. The markdown is generated by the SaaS (from the catalogue
 * + brand identity) and stored here; it is served at the domain root by the
 * `llms` front controller (the /llms.txt route). Purely additive: writes only to
 * its own table, never touches catalogue data.
 */
class LlmsTxtTools
{
    private const MAX_BYTES = 100000;
    private const TABLE = 'fexa_ai_llms_txt';

    #[McpTool(
        name: 'set_llms_txt',
        description: 'Store the shop /llms.txt markdown, served at the domain root (/llms.txt). Upserts by (id_shop, id_lang).'
    )]
    #[Schema(
        properties: [
            'content' => ['type' => 'string', 'description' => 'Full llms.txt markdown (must contain a "# " H1).'],
            'id_shop' => ['type' => 'integer', 'description' => 'Shop ID (0 = all shops, default)'],
            'id_lang' => ['type' => 'integer', 'description' => 'Language ID (0 = default, default)'],
        ],
        required: ['content']
    )]
    public function setLlmsTxt(string $content, ?int $id_shop = 0, ?int $id_lang = 0): array
    {
        $id_shop = (int) $id_shop;
        $id_lang = (int) $id_lang;
        $content = trim($this->maybeDecodeBase64($content));

        if ($content === '') {
            throw new \Exception('content is empty');
        }
        if (strlen($content) > self::MAX_BYTES) {
            throw new \Exception('content too large');
        }
        // Must look like an llms.txt: at least one markdown H1. We never serve
        // arbitrary content at the domain root.
        if (!preg_match('/^#\s+/m', $content)) {
            throw new \Exception('content must contain a markdown H1 (a line starting with "# ")');
        }

        // Self-heal: create the table if a prior install/upgrade missed it. Without this,
        // a missing table made the INSERT fail silently while we still returned success —
        // the row was never stored and /llms.txt kept 404-ing.
        $this->ensureTable();

        $db = Db::getInstance();
        $c = pSQL($content, true);
        $where = 'id_shop = ' . $id_shop . ' AND id_lang = ' . $id_lang;
        $db->delete(self::TABLE, $where);
        $ok = $db->execute(
            'INSERT INTO `' . _DB_PREFIX_ . self::TABLE . '` (id_shop, id_lang, content, is_active) VALUES '
            . '(' . $id_shop . ', ' . $id_lang . ", '" . $c . "', 1)"
        );

        // Verify the write actually persisted — never report a false success.
        $stored = (int) $db->getValue(
            'SELECT COUNT(*) FROM `' . _DB_PREFIX_ . self::TABLE . '` WHERE ' . $where
        );
        if (!$ok || $stored < 1) {
            throw new \Exception('llms.txt write did not persist (database error or insufficient privileges)');
        }

        return [
            'status' => 'success',
            'id_shop' => $id_shop,
            'id_lang' => $id_lang,
            'bytes' => strlen($content),
        ];
    }

    /** Decode a WAF-safe base64 transport. Real llms.txt markdown always contains spaces,
     *  '#' and newlines (none of which are in the base64 alphabet), so a payload that is a
     *  single pure base64 token is the SaaS sending the content encoded to dodge web-app
     *  firewalls (e.g. Atomicorp rule 360151 flags the markdown link syntax "[x](y)" as a
     *  PHP-injection attempt). Plain markdown is returned untouched. */
    private function maybeDecodeBase64(string $content): string
    {
        $t = trim($content);
        if ($t !== '' && preg_match('/^[A-Za-z0-9+\/]+={0,2}$/', $t)) {
            $decoded = base64_decode($t, true);
            if ($decoded !== false && $decoded !== '') {
                return $decoded;
            }
        }

        return $content;
    }

    /** Create the storage table if missing — mirrors sql/install.sql so a push always has
     *  somewhere to write, even when the module was upgraded over a build that predates it. */
    private function ensureTable(): void
    {
        Db::getInstance()->execute(
            'CREATE TABLE IF NOT EXISTS `' . _DB_PREFIX_ . self::TABLE . '` ('
            . '`id` INT(10) UNSIGNED AUTO_INCREMENT,'
            . '`id_shop` INT(10) UNSIGNED NOT NULL DEFAULT 0,'
            . '`id_lang` INT(10) UNSIGNED NOT NULL DEFAULT 0,'
            . '`content` LONGTEXT NOT NULL,'
            . '`is_active` TINYINT(1) NOT NULL DEFAULT 1,'
            . '`updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,'
            . 'PRIMARY KEY (`id`),'
            . 'UNIQUE KEY `uq_shop_lang` (`id_shop`, `id_lang`)'
            . ') ENGINE = ' . _MYSQL_ENGINE_ . ' DEFAULT CHARSET = utf8'
        );
    }

    #[McpTool(
        name: 'get_llms_txt',
        description: 'Read the stored /llms.txt for a shop (diff / delivery verification).'
    )]
    #[Schema(
        properties: [
            'id_shop' => ['type' => 'integer', 'description' => 'Shop ID (0 = default)'],
            'id_lang' => ['type' => 'integer', 'description' => 'Language ID (0 = default)'],
        ],
        required: []
    )]
    public function getLlmsTxt(?int $id_shop = 0, ?int $id_lang = 0): array
    {
        $id_shop = (int) $id_shop;
        $id_lang = (int) $id_lang;
        $this->ensureTable();

        $row = Db::getInstance()->getRow(
            'SELECT content, is_active, updated_at FROM `' . _DB_PREFIX_ . self::TABLE . '` '
            . 'WHERE id_shop = ' . $id_shop . ' AND id_lang = ' . $id_lang . ' LIMIT 1'
        );

        return [
            'id_shop' => $id_shop,
            'id_lang' => $id_lang,
            'content' => is_array($row) && isset($row['content']) ? $row['content'] : null,
            'is_active' => is_array($row) ? (int) ($row['is_active'] ?? 0) : 0,
            'updated_at' => is_array($row) ? ($row['updated_at'] ?? null) : null,
        ];
    }

    #[McpTool(
        name: 'delete_llms_txt',
        description: 'Remove the stored /llms.txt for a shop (the route then returns 404).'
    )]
    #[Schema(
        properties: [
            'id_shop' => ['type' => 'integer', 'description' => 'Shop ID (0 = default)'],
            'id_lang' => ['type' => 'integer', 'description' => 'Language ID (0 = default)'],
        ],
        required: []
    )]
    public function deleteLlmsTxt(?int $id_shop = 0, ?int $id_lang = 0): array
    {
        $id_shop = (int) $id_shop;
        $id_lang = (int) $id_lang;

        Db::getInstance()->delete(self::TABLE, 'id_shop = ' . $id_shop . ' AND id_lang = ' . $id_lang);

        return ['status' => 'deleted', 'id_shop' => $id_shop, 'id_lang' => $id_lang];
    }
}
